fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    // `best` will hold the current longest sequence we've seen so far.
    // If `strings` is empty, `best` will remain `None`.
    let mut best: Option<Vec<char>> = None;

    for seq in strings {
        // We decide to replace `best` if:
        //   1) `best` is `None` (i.e. this is the first sequence), or
        //   2) `seq.len()` is strictly greater than the length of the current `best`.
        let replace = match &best {
            None => true,
            Some(bs) => seq.len() > bs.len(),
        };

        if replace {
            best = Some(seq);
        }
        // If `seq.len() == best.len()`, we do nothing,
        // thereby preserving the earliest maximum-length sequence.
    }

    best
}

